package com.example.data

import android.content.Context
import org.json.JSONObject

/**
 * Parsed view of assets/studyplan/plan.json.
 *
 * The plan contains NO secrets: it is generated by scripts/build_plan_asset.py
 * from the PW API and contains only course/chapter/lecture structure, DPP PDF
 * links and pre-recorded completion flags.
 */
data class PwDppEntry(val name: String, val url: String)

data class PwLectureEntry(
    val pwId: String,
    val title: String,
    val date: String,
    val durationMin: Long,
    val isCompleted: Boolean
)

data class PwChapterEntry(
    val topicId: String,
    val name: String,
    val dpps: List<PwDppEntry>,
    val lectures: List<PwLectureEntry>
)

data class PwCoursePlan(
    val key: String,
    val source: String,
    val subjectGroup: String, // physics / chemistry / maths
    val playlistUrl: String,
    val fullyComplete: Boolean,
    val chapters: List<PwChapterEntry>
)

data class PwStudyPlan(val courses: List<PwCoursePlan>) {

    val lectureTotal: Int
        get() = courses.sumOf { c -> c.chapters.sumOf { it.lectures.size } }
}

object PwStudyPlan {

    const val ASSET_PATH = "studyplan/plan.json"

    /** Parses the plan asset. Returns null (never throws) when the asset is missing/corrupt. */
    fun fromAssets(context: Context): PwStudyPlan? = try {
        context.assets.open(ASSET_PATH).use { stream ->
            val bytes = stream.readBytes()
            parse(String(bytes, Charsets.UTF_8))
        }
    } catch (e: Exception) {
        null
    }

    fun parse(json: String): PwStudyPlan? = try {
        val root = JSONObject(json)
        val coursesJson = root.getJSONArray("courses")
        val courses = mutableListOf<PwCoursePlan>()
        for (i in 0 until coursesJson.length()) {
            val cJson = coursesJson.getJSONObject(i)
            val chapters = mutableListOf<PwChapterEntry>()
            val chaptersJson = cJson.optJSONArray("chapters")
            if (chaptersJson != null) {
                for (j in 0 until chaptersJson.length()) {
                    val chJson = chaptersJson.getJSONObject(j)
                    val dpps = mutableListOf<PwDppEntry>()
                    val dppsJson = chJson.optJSONArray("dpps")
                    if (dppsJson != null) {
                        for (k in 0 until dppsJson.length()) {
                            val dJson = dppsJson.getJSONObject(k)
                            val name = dJson.optString("name", "DPP.pdf")
                            val url = dJson.optString("url", "")
                            if (url.startsWith("https://")) {
                                dpps.add(PwDppEntry(name = name, url = url))
                            }
                        }
                    }
                    val lectures = mutableListOf<PwLectureEntry>()
                    val lecturesJson = chJson.optJSONArray("lectures")
                    if (lecturesJson != null) {
                        for (k in 0 until lecturesJson.length()) {
                            val lJson = lecturesJson.getJSONObject(k)
                            lectures.add(
                                PwLectureEntry(
                                    pwId = lJson.optString("pwId", ""),
                                    title = lJson.optString("title", ""),
                                    date = lJson.optString("date", ""),
                                    durationMin = lJson.optLong("durationMin", 0L),
                                    isCompleted = lJson.optBoolean("isCompleted", false)
                                )
                            )
                        }
                    }
                    chapters.add(
                        PwChapterEntry(
                            topicId = chJson.optString("topicId", ""),
                            name = chJson.optString("name", ""),
                            dpps = dpps,
                            lectures = lectures
                        )
                    )
                }
            }
            courses.add(
                PwCoursePlan(
                    key = cJson.optString("key", ""),
                    source = cJson.optString("source", ""),
                    subjectGroup = cJson.optString("subjectGroup", "chemistry"),
                    playlistUrl = cJson.optString("playlistUrl", ""),
                    fullyComplete = cJson.optBoolean("fullyComplete", false),
                    chapters = chapters
                )
            )
        }
        if (courses.isEmpty()) null else PwStudyPlan(courses = courses)
    } catch (e: Exception) {
        null
    }

    /** "physics" -> "Physics" */
    fun PwCoursePlan.subjectTitle(): String = when (subjectGroup.lowercase()) {
        "physics" -> "Physics"
        "maths" -> "Maths"
        else -> "Chemistry"
    }
}
